package com.onlymymoney.adapter.out.persistence;

import jakarta.persistence.*;

import java.math.BigDecimal;
import java.time.LocalDate;

/**
 * JPA entity mapped to the {@code budgets} table.
 * <p>
 * It is the persistence representation of a budget: an amount assigned to a category
 * for a given period of time.
 */
@Entity
@Table(name = "budgets")
public class BudgetJpa {
    /** Primary key, generated by the database (identity column). */
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    Long id;
    /** Identifier of the category this budget belongs to. */
    @Column(name = "category_id")
    Long categoryId;
    /** First day of the budget period. */
    @Column(name = "period_start")
    LocalDate periodStart;
    /** Last day of the budget period. */
    @Column(name = "period_end")
    LocalDate periodEnd;
    /** Budgeted amount. */
    BigDecimal amount;

    /**
     * Default constructor required by JPA.
     */
    public BudgetJpa() {
    }

    /**
     * Creates an entity with all its fields.
     *
     * @param id the identifier ({@code null} for a new budget)
     * @param c  the category identifier
     * @param s  the period start date
     * @param e  the period end date
     * @param a  the budgeted amount
     */
    public BudgetJpa(Long id, Long c, LocalDate s, LocalDate e, BigDecimal a) {
        this.id = id;
        categoryId = c;
        periodStart = s;
        periodEnd = e;
        amount = a;
    }

    /** @return the budget identifier */
    public Long getId() {
        return id;
    }

    /** @return the identifier of the category the budget belongs to */
    public Long getCategoryId() {
        return categoryId;
    }

    /** @return the first day of the budget period */
    public LocalDate getPeriodStart() {
        return periodStart;
    }

    /** @return the last day of the budget period */
    public LocalDate getPeriodEnd() {
        return periodEnd;
    }

    /** @return the budgeted amount */
    public BigDecimal getAmount() {
        return amount;
    }
}